        omitted.add("systemPrompt");
        break;
      case "--append-system-prompt":
        take();
        omitted.add("appendSystemPrompt");
        break;
      case "--recall-query":
        take();
        omitted.add("recallQuery");
        break;
      case "--image":
        take();
        omitted.add("initialImage");
