        break;
      case "--settings":
        settingsFile = scalar(take(), 4096);
        break;
      case "--bundle":
        bundle = scalar(take(), 4096);
        break;
      case "--add-dir":
        addDirs.push(take());
        break;
      case "--max-turns":
        profile.budget.maxTurns = policyBudget(takePolicy(), "maxTurns");
        break;
      case "--max-budget-usd":
